enum EyeEasing : uint8_t {
  EYE_EASE_LINEAR = 0,
  EYE_EASE_IN,
  EYE_EASE_OUT,
  EYE_EASE_INOUT,
  EYE_EASE_BOUNCE,
  EYE_EASE_ELASTIC,
  EYE_EASE_BEZIER
};

struct EyeFrame {
  uint8_t width, height, radius;
  int16_t rotation; // Eye Rotation, degrees -180..180 (int16_t so it isn't capped at int8's ±127)
  uint8_t distance;
  int8_t eyePosX, eyePosY; // -100..100px, moves this whole eye on top of the ±distance/2 placement — see EyeParams.eyePosX's own comment in the studio
  uint8_t irisWidth, irisHeight;
  uint8_t pupilWidth, pupilHeight;
  int8_t pupilX, pupilY;
  uint16_t pupilRotation; // degrees, 0-360
  uint8_t upperEyelid, lowerEyelid;
  int8_t upperEyelidTilt, lowerEyelidTilt; // degrees, -45..45
  int8_t upperEyelidCurvature, lowerEyelidCurvature; // -100 (inward) to 100 (outward), 0 = flat
  uint8_t upperEyelidLeftRoundness, upperEyelidRightRoundness; // 0-100 each, independent per end (see EyeParams.upperEyelidLeftRoundness's own comment in the studio)
  uint8_t lowerEyelidLeftRoundness, lowerEyelidRightRoundness; // 0-100 each
  uint8_t upperEyelidStretchX, lowerEyelidStretchX; // 0-200 (Curve Width; >100 = broader/flatter arc; fits uint8_t)
  uint8_t upperEyelidStretchY, lowerEyelidStretchY; // 0-200
  int8_t upperEyelidSkew, lowerEyelidSkew; // -100..100, "Center Position X" — see eyesEyelidTaper()
  uint8_t upperEyelidCenterDepth, lowerEyelidCenterDepth; // 0-100
  int8_t upperEyelidCenterY, lowerEyelidCenterY; // -100..100
  uint8_t upperEyelidSmoothness, lowerEyelidSmoothness; // 0-100
  uint8_t upperEyelidTension, lowerEyelidTension; // 0-100
  uint8_t upperEyelidThickness, lowerEyelidThickness; // crease/rim line width in px (0-200), the studio's Thickness control
  int8_t highlightX, highlightY;
  uint8_t highlightSize;
  uint16_t durationMs;
  uint8_t easing;
  int8_t bezierX1, bezierY1, bezierX2, bezierY2;
  uint8_t pupilShape; // an EyePupilShape value — see the enum + shape tables below
  uint8_t pupilCustomShapeIndex; // index into PUPIL_CUSTOM_SHAPES, only meaningful when pupilShape == EYE_PUPIL_SHAPE_CUSTOM
  bool pupilVisible; // Layers panel — false skips the pupil draw call entirely
  uint8_t eyeShape; // an EyeShapeId value — see the enum + shape tables below. Already folded
                     // down to EYE_SHAPE_DEFAULT when the studio's eyeShapeVisible is false.
  uint8_t eyeCustomShapeIndex; // index into EYE_CUSTOM_SHAPES, only meaningful when eyeShape == EYE_SHAPE_CUSTOM
  uint8_t eyeShapeScale; // 50-200%, no effect when eyeShape == EYE_SHAPE_DEFAULT
  int8_t eyeShapeOffsetX, eyeShapeOffsetY; // -30..30px, shifts the eye's own silhouette for every eyeShape, including EYE_SHAPE_DEFAULT
  bool eyeShapeFlipH, eyeShapeFlipV;
  bool upperEyelidVisible, lowerEyelidVisible; // Layers panel — false renders as if coverage were 0
  bool irisVisible;      // Eye Controls — false hides the iris entirely (settings kept)
  bool highlightVisible; // Eye Controls — false hides the highlight glint entirely (settings kept)
  bool disableEyelid;    // "Disable Eyelid" — true skips the eye-shape border ring entirely so no
                         // outline shows around the eyelid-covered part of the eye (eye contents +
                         // eyelid clip are untouched). Mirrors the studio's drawEye.ts.
  // Extra highlight glints beyond the primary highlight above (see EyeParams.extraHighlights).
  // exHlCount live slots of 1; each x/y is -40..40 (% of pupil/iris radius), size 0..60 (%).
  // All share the single highlight color (EYE_COLOR_HIGHLIGHT / EyeColorSet.highlightBlend).
  uint8_t exHlCount;
  int8_t exHlX[1];
  int8_t exHlY[1];
  uint8_t exHlSize[1];
  bool exHlVisible[1];
};

// One eye's full color palette (RGB565) plus its border thickness — the studio's Eye
// Target: Left/Right editing lets the two eyes end up with different palettes (and
// different border widths, via Visual Reference per-eye overrides), so this is a value
// passed to the drawing functions rather than fixed macros. sclera/iris/pupil/highlight/
// shadow/glow/border are the raw or opacity-blended colors (see colorSetLiteral() in the
// studio's cppExport.ts); scleraTop/Bottom, irisLight/Dark, and highlightBlend are additional
// precomputed values the gradient/glow/shadow drawing routines below use, approximating what
// the studio preview renders as true Canvas 2D gradients/blur (Adafruit_GFX has neither).
struct EyeColorSet {
  uint16_t sclera, iris, pupil, highlight, shadow, glow, border;
  uint8_t borderWidth; // ring thickness in pixels
  uint8_t shadowIntensity, glowIntensity; // 0-100, straight from the Color panel
  uint16_t scleraTop, scleraBottom; // sclera gradient endpoints
  uint16_t irisLight, irisDark; // iris radial-gradient endpoints (iris itself is the midpoint)
  uint16_t highlightBlend; // highlight pre-blended 92% over the pupil, matching the studio's fixed-alpha look
  uint16_t upperEyelidFill, lowerEyelidFill; // eyelid color pre-blended over the background by Eyelid Opacity
  uint16_t upperEyelidCrease, lowerEyelidCrease; // the Thickness crease line: eyelid color 35% darker, same opacity blend
};

// ---- Colors -----------------------------------------------------------

#define EYE_COLOR_BACKGROUND 0x0000 // RGB565 — Display panel's background color
#define EYE_DISPLAY_WIDTH  240  // Display panel size (studio's Display panel) — used to center the eyes
#define EYE_DISPLAY_HEIGHT 240

// sclera, iris, pupil, highlight, shadow, glow, border, borderWidth, shadowIntensity,
// glowIntensity, scleraTop, scleraBottom, irisLight, irisDark, highlightBlend,
// upperEyelidFill, lowerEyelidFill, upperEyelidCrease, lowerEyelidCrease — see the
// comment above colorSetLiteral() in the studio's cppExport.ts for what each precomputed
// field is for (border/pupil/highlight/eyelid opacity and the sclera/iris gradients all have
// no RGB565 alpha channel to work with, so they're pre-blended here).
const EyeColorSet EYE_COLORS_LEFT = { 0xFFFF, 0x8F7D, 0x8F7D, 0xFFFF, 0x0002, 0xEFFF, 0x0000, 4, 20, 10, 0xFFFF, 0xE73C, 0x9F9D, 0x6DD6, 0xF7FF, 0x0000, 0x0000, 0x0000, 0x0000 };
const EyeColorSet& EYE_COLORS_RIGHT = EYE_COLORS_LEFT;  // identical to the left eye — shared, no duplicate data

