// ---- Animation Combinations -----------------------------------------------
/*
 * Animation Combinations
 *
 * Play multiple animations as one reusable sequence.
 *
 * Play:
 *
 *   Combo(<yourCombo>);   // loop defaults to false -- see the Quick Reference at the
 *                          // top of this file for the optional loop argument
 *
 * Play several combos back-to-back (each starts only after the previous finishes):
 *
 *   PlayMultipleCombos({ &WakeUp, &IdleLookUp, &Idle });        // play each once, then hold the last
 *   PlayMultipleCombos({ &Idle, &IdleLookUp }, true);           // loop the whole list: Idle -> IdleLookUp -> Idle -> ...
 *   // Pass combo POINTERS (&Name). Every combo plays once in order; with loop==true the whole
 *   // list repeats (index wraps to 0 after the last). Any Combo()/PlayAnimation() cancels the queue.
 *
 * Stop:
 *
 *   StopCombo();
 *
 * Pause:
 *
 *   PauseCombo();
 *
 * Resume:
 *
 *   ResumeCombo();
 *
 * Restart:
 *
 *   RestartCombo();
 *
 * Status:
 *
 *   ComboPlaying();
 *   ComboPaused();
 *   ComboFinished();
 *   ComboSequencePlaying();   // true while a PlayMultipleCombos() queue is running
 *
 */
