// ---- Example (opt-in) --------------------------------------------------------
// Define EYES_ENABLE_DEMO and the five TFT_* pin macros before #include "eyes.h" to get
// a ready-to-flash sketch below — no other code needed. Example:
//
//   #define EYES_ENABLE_DEMO
//   #define TFT_CS   2
//   #define TFT_DC   4
//   #define TFT_RST  5
//   #define TFT_SCLK 6
//   #define TFT_MOSI 7
//   #include <SPI.h>
//   #include <Adafruit_GC9A01A.h>
//   #include "eyes.h"
//
// Leave EYES_ENABLE_DEMO undefined and write your own setup()/loop() instead — that's
// the whole point of SetExpression()/PlayAnimation()/UpdateEyes() above: your sketch only
// needs to be this short (see "Minimal usage" at the top of this file for the full copy-
// paste version).
#ifdef EYES_ENABLE_DEMO

// ---- Initialization -----------------------------------------------------------
EyesBufferedDisplay tft(TFT_CS, TFT_DC, TFT_RST);

// ---- Expression control ---------------------------------------------------------
// Cycles through every expression a few seconds apart, purely to show them off.
// Replace this timer with your own trigger — a button, a sensor, a serial command,
// anything — that calls SetExpression() whenever you actually want the eyes to change.
const EyeExpression* const demoExpressions[] = { &Expr_ExcitedIdle, &Expr_ExcitedLookFront };
const char* const demoExpressionNames[] = { "Excited Idle", "Excited Look Front" };
const int demoExpressionCount = 2;
int demoExprIndex = -1;
unsigned long demoExprCycleStart = 0;

void demoCycleExpressions() {
  if (millis() - demoExprCycleStart < 2500) return;
  demoExprCycleStart = millis();
  demoExprIndex = (demoExprIndex + 1) % demoExpressionCount;
  Serial.print("Expression: ");
  Serial.println(demoExpressionNames[demoExprIndex]);
  SetExpression(*demoExpressions[demoExprIndex]);
}

// ---- Animation control ---------------------------------------------------------
// Starts the eyes off playing "Example" as an idle filler below. Call
// PlayAnimation(Anim_Whatever) any time you want to switch to a different animation —
// see the Quick Reference above for every name this project exports.

// ---- Main update loop ---------------------------------------------------------
void setup() {
  Serial.begin(115200);
  SPI.begin(TFT_SCLK, -1, TFT_MOSI, TFT_CS);
  tft.begin();
  tft.setRotation(0);
  PlayAnimation(Anim_Example);
  demoExprCycleStart = millis();
}

void loop() {
  demoCycleExpressions();

  LiveEye live = UpdateEyes();
  LiveEye liveRight = UpdateEyesRight();  // only differs from `live` while playing an animation that
                                          // authored real Left Eye/Right Eye track divergence in the
                                          // studio — always safe to call either way
  tft.fillScreen(EYE_COLOR_BACKGROUND);
  eyesDrawEyePair(tft, 120, 120, live, liveRight, EYE_COLOR_BACKGROUND, eyesPlayer.colorsLeft, eyesPlayer.colorsRight);  // also draws this project's/the active expression's/animation's stickers, and the active expression's own colors
  tft.present();
  delay(EYE_FRAME_DELAY_MS);
}

#endif // EYES_ENABLE_DEMO

#endif // EYES_EYE_ANIMATIONS_SPIDERMAN_H
